"use client";

import { MorphingTabs } from "@/components/application/animations/expanded/controls/morphing-tabs";

export default function Example() {
  return (
    <MorphingTabs
      items={[
        {
          "id": "upper",
          "label": "Upper",
          "image": {
            "src": "/assets/zeus/product_shoe_06.jpg",
            "alt": "Engineered running shoe upper"
          },
          "content": "Start with a lightweight engineered mesh upper, then explore the details that define its shape. This sample panel combines an image with a longer description so you can see how the connected surface handles different amounts of text."
        },
        {
          "id": "midsole",
          "label": "Midsole",
          "image": {
            "src": "/assets/zeus/product_shoe_06.jpg",
            "alt": "Running shoe midsole"
          },
          "content": "This sample midsole description explores dual-density construction as a product detail. Replace it with your own specifications, imagery, or a richer React layout. The panel measures the resulting content and keeps the active tab connected as its dimensions change."
        },
        {
          "id": "outsole",
          "label": "Outsole",
          "image": {
            "src": "/assets/zeus/product_football-boot_01.jpg",
            "alt": "Performance outsole"
          },
          "content": "Use the outsole tab to show a second view of your product. A close-up image, material notes, and a few useful comparisons can help people understand the design. All of this content comes from the item data you provide."
        },
        {
          "id": "fit",
          "label": "Fit",
          "image": {
            "src": "/assets/zeus/product_shoe_06.jpg",
            "alt": "Running shoe fit"
          },
          "content": "Give customers practical guidance in the fit panel. You can include a sizing table, a measurement illustration, or a short explanation of available options. This example keeps the content brief to show the transition to a smaller panel."
        }
      ]}
      duration={0.65}
      background={"#111111"}
      color={"#eeece8"}
      gap={4}
      fillet={22}
    />
  );
}

